// Agoda — grid paths: right/down minimum sum (LeetCode 64), any-direction minimum weight (Dijkstra),
// and counting paths around obstacles (LeetCode 63).
public static class GridPaths {
    // Moving only right or down from the top-left to the bottom-right; the cost is the sum of every cell visited.
    public static int MinPathSumRightDown(int[][] grid) {
        if (grid == null || grid.Length == 0 || grid[0].Length == 0) throw new ArgumentException("empty grid");
        int R = grid.Length, C = grid[0].Length;
        var dp = new long[C];
        for (int r = 0; r < R; r++)
            for (int c = 0; c < C; c++) {
                long best = r == 0 && c == 0 ? 0 : long.MaxValue;
                if (r > 0) best = Math.Min(best, dp[c]);
                if (c > 0) best = Math.Min(best, dp[c - 1]);
                dp[c] = best + grid[r][c];
            }
        return (int)dp[C - 1];
    }

    // Moving up/down/left/right; negative cells are walls. Cost = sum of every cell on the path, both ends
    // included. Returns -1 if `to` cannot be reached.
    public static long MinPathWeight(int[][] grid, int fromR, int fromC, int toR, int toC) {
        if (grid == null || grid.Length == 0) throw new ArgumentException("empty grid");
        int R = grid.Length, C = grid[0].Length;
        bool In(int r, int c) => r >= 0 && r < R && c >= 0 && c < C;
        if (!In(fromR, fromC) || !In(toR, toC)) throw new ArgumentOutOfRangeException("point outside the grid");
        if (grid[fromR][fromC] < 0 || grid[toR][toC] < 0) return -1;
        var dist = new long[R, C];
        for (int r = 0; r < R; r++) for (int c = 0; c < C; c++) dist[r, c] = long.MaxValue;
        var pq = new PriorityQueue<(int R, int C), long>();
        dist[fromR, fromC] = grid[fromR][fromC]; pq.Enqueue((fromR, fromC), dist[fromR, fromC]);
        int[] dr = { 1, -1, 0, 0 }, dc = { 0, 0, 1, -1 };
        while (pq.TryDequeue(out var cur, out var d)) {
            if (d != dist[cur.R, cur.C]) continue;           // stale entry
            if (cur.R == toR && cur.C == toC) return d;
            for (int k = 0; k < 4; k++) {
                int nr = cur.R + dr[k], nc = cur.C + dc[k];
                if (!In(nr, nc) || grid[nr][nc] < 0) continue;
                long nd = d + grid[nr][nc];
                if (nd < dist[nr, nc]) { dist[nr, nc] = nd; pq.Enqueue((nr, nc), nd); }
            }
        }
        return -1;
    }

    // 1 = obstacle. Number of right/down paths from top-left to bottom-right.
    public static long UniquePathsWithObstacles(int[][] grid) {
        if (grid == null || grid.Length == 0 || grid[0].Length == 0) return 0;
        int C = grid[0].Length;
        var dp = new long[C];
        dp[0] = grid[0][0] == 1 ? 0 : 1;
        foreach (var row in grid)
            for (int c = 0; c < C; c++) {
                if (row[c] == 1) dp[c] = 0;
                else if (c > 0) dp[c] += dp[c - 1];
            }
        return dp[C - 1];
    }
}
