            Expect.Do("single cell", () => { Expect.Eq("single cell", GridPaths.MinPathSumRightDown(new[] { new[] { 5 } }), 5); });
        } catch (Exception e) { Expect.Setup(e); }
        Expect.Summary(3);
    }
